using System;using System.Collections;using System.Reflection;using UnityEngine;using UnityEngine.UI;
public sealed class NetworkGroupTests:MonoBehaviour
{
 const BindingFlags IP=BindingFlags.Instance|BindingFlags.NonPublic,SP=BindingFlags.Static|BindingFlags.NonPublic;static bool booted;bool host;object net;int checks,failures;float began;
 public static void Boot(){if(booted)return;booted=true;var o=new GameObject("NetworkGroupTests");DontDestroyOnLoad(o);o.AddComponent<NetworkGroupTests>();}
 object Field(string name){return typeof(LanMultiplayer).GetField(name,IP).GetValue(net);}void Call(string name,params object[] args){typeof(LanMultiplayer).GetMethod(name,IP).Invoke(net,args);}
 void Check(bool ok,string label){checks++;if(!ok)failures++;Debug.Log("GROUPPAIR "+(ok?"PASS ":"FAIL ")+label);}
 Button Button(string name){foreach(var b in FindObjectsOfType<Button>())if(b.name==name)return b;return null;}
 IEnumerator Start(){began=Time.realtimeSinceStartup;Application.runInBackground=true;Application.targetFrameRate=100;QualitySettings.vSyncCount=0;AudioListener.volume=0;host=Array.IndexOf(Environment.GetCommandLineArgs(),"-network-host")>=0;yield return new WaitForSeconds(.4f);
  var main=(Component)typeof(GameAIMod).GetField("menuPanel",SP).GetValue(null);var template=main.GetComponentInChildren<Button>(true);var canvas=main.GetComponentInParent<Canvas>();PlayerSkills.Enabled=true;AbilityMode.Enabled=false;LanMultiplayer.OpenLobby(true,delegate{},canvas.transform,template);net=typeof(LanMultiplayer).GetField("instance",SP).GetValue(null);
  if(host)Call("StartHost");else {yield return new WaitForSeconds(1f);Call("Join","127.0.0.1");}
  float until=Time.realtimeSinceStartup+10f;while(Field("state").ToString()!="Connected"&&Time.realtimeSinceStartup<until)yield return null;Check(Field("state").ToString()=="Connected","two independent players connected through production UDP handshake");
  Call("ChooseRole",host?0:1);until=Time.realtimeSinceStartup+8f;while(((int)Field("hostRole")<0||(int)Field("guestRole")<0||Field("pendingCommand")!=null)&&Time.realtimeSinceStartup<until)yield return null;Check((int)Field("hostRole")==0&&(int)Field("guestRole")==1,"roles remain independently selected before choosing skill groups");Call("Prepare");
  until=Time.realtimeSinceStartup+8f;while((int)Field("roomPhase")!=1&&Time.realtimeSinceStartup<until)yield return null;yield return null;Check((int)Field("roomPhase")==1&&!LanMultiplayer.Active&&FindObjectOfType<SkillGroupPanel>()!=null,"special room opens each player's group selector before match starts");
  Button("Group Select "+(host?1:0)).onClick.Invoke();yield return new WaitForSeconds(.65f);Check(SkillGroups.Group(host?0:1)==(host?1:0),"room heartbeats preserve unfinished local group choice");Button("Group Confirm").onClick.Invoke();
  until=Time.realtimeSinceStartup+12f;while(!LanMultiplayer.Active&&Time.realtimeSinceStartup<until)yield return null;yield return new WaitForSeconds(1.2f);Check(LanMultiplayer.Active&&GameObject.Find("Fan")!=null&&GameObject.Find("Zhao")!=null,"match starts only after both group confirmations");
  var type=Type.GetType("PlayerController, Assembly-CSharp");var fan=GameObject.Find("Fan").GetComponent(type);var zhao=GameObject.Find("Zhao").GetComponent(type);bool masks=true;for(int i=0;i<AbilityMode.Skills.Length;i++){masks&=SkillRework.Has(fan,i)==((SkillGroups.Defense&(1<<i))!=0);masks&=SkillRework.Has(zhao,i)==((SkillGroups.Attack&(1<<i))!=0);}Check(masks,"host and guest agree on swapped skill ownership in the actual match");Check(AbilityMode.Runtime&&!AbilityMode.Enabled&&fan.GetComponent<BuildPlayer>()!=null&&zhao.GetComponent<BuildPlayer>()!=null,"special group gameplay is active on both ends without enabling point allocation");
  if(host){var actor=zhao;var other=fan;var nativeBall=(FindObjectOfType(type.Assembly.GetType("Ball")) as Component).GetComponent<Rigidbody2D>();var body=(Rigidbody2D)type.GetField("rb").GetValue(actor);foreach(var a in new[]{actor,other})foreach(var rb in a.GetComponentsInChildren<Rigidbody2D>())rb.constraints=RigidbodyConstraints2D.FreezeAll;Move(actor,new Vector2(2,body.position.y),type);Move(other,new Vector2(-5,body.position.y),type);var head=actor.transform.Find("Head").GetComponent<Collider2D>();nativeBall.position=new Vector2(head.bounds.center.x,head.bounds.max.y+nativeBall.GetComponent<Collider2D>().bounds.extents.y-.01f);nativeBall.velocity=Vector2.down*.5f;nativeBall.gravityScale=0;Physics2D.SyncTransforms();PlayerSkills.SetAction((Animator)type.GetField("anim").GetValue(actor),"Head",actor);for(int i=0;i<3;i++)yield return new WaitForFixedUpdate();Move(other,new Vector2(nativeBall.position.x-2.5f,nativeBall.position.y+nativeBall.velocity.y*.15f),type);}
  until=Time.realtimeSinceStartup+6f;while(SkillRework.ResilienceStacks(zhao)==0&&Time.realtimeSinceStartup<until)yield return null;Check(SkillRework.ResilienceStacks(zhao)==1&&SkillRework.ShootingLevel(zhao)==5.5f,"real blocked shot and fractional bonus replicate from host to guest");
  yield return new WaitForSeconds(.5f);if(host){var m=FindObjectOfType(type.Assembly.GetType("GameManager")) as MonoBehaviour;m.StartCoroutine((IEnumerator)m.GetType().GetMethod("Goal").Invoke(m,new object[]{true}));}
  until=Time.realtimeSinceStartup+6f;while(SkillRework.ResilienceStacks(zhao)>0&&Time.realtimeSinceStartup<until)yield return null;Check(SkillRework.ResilienceStacks(zhao)==0,"native goal clears the replicated bonus on both ends");
  yield return new WaitForSeconds(2.8f);
  if(host){var a=zhao;var other=fan;foreach(var rb in a.GetComponentsInChildren<Rigidbody2D>())rb.constraints=RigidbodyConstraints2D.None;var skill=a.GetComponent<SkillRework>();float floor=GameObject.Find("Down").GetComponent<Collider2D>().bounds.max.y,standing=(float)typeof(SkillRework).GetField("standingBodyHeight",IP).GetValue(skill);Move(a,new Vector2(0,floor+standing),type);Move(other,new Vector2(5,((Rigidbody2D)type.GetField("rb").GetValue(other)).position.y),type);var football=(FindObjectOfType(type.Assembly.GetType("Ball")) as Component).GetComponent<Rigidbody2D>();float scale=Mathf.Abs(a.transform.lossyScale.x)/.8f;football.position=((Rigidbody2D)type.GetField("rb").GetValue(a)).position+new Vector2(.58f*scale,1.2f*scale);football.velocity=Vector2.zero;football.gravityScale=0;Physics2D.SyncTransforms();for(int n=0;n<100;n++){UnityEngine.Random.InitState(n);if(UnityEngine.Random.value<.5f){UnityEngine.Random.InitState(n);break;}}}
  bool mirrorSeen=false,mirrorRestored=false;until=Time.realtimeSinceStartup+8f;while(Time.realtimeSinceStartup<until){mirrorSeen|=SkillRework.Mirrored(zhao);if(mirrorSeen&&!SkillRework.Mirrored(zhao)){mirrorRestored=true;break;}yield return null;}Check(mirrorSeen,"actual bicycle mirror state reaches both host and guest");Check(mirrorRestored&&!SkillRework.InBicycle(zhao)&&zhao.transform.localScale.x>0,"standing recovery restores facing and releases action lock on both network players");
  yield return new WaitForSeconds(1.5f);Check(LanMultiplayer.Active&&(int)Field("receiveSequence")>=0,"gameplay snapshots continue after the new pre-match phase");Call("StopSession");Debug.Log("GROUPPAIR COMPLETE role="+(host?"host":"guest")+" checks="+checks+" failures="+failures);Application.Quit(failures==0?0:1);
 }
 void Move(Component a,Vector2 position,Type t){var body=(Rigidbody2D)t.GetField("rb").GetValue(a);a.transform.position+=(Vector3)(position-body.position);foreach(var rb in a.GetComponentsInChildren<Rigidbody2D>()){rb.velocity=Vector2.zero;rb.angularVelocity=0;}Physics2D.SyncTransforms();}
 void Update(){if(Time.realtimeSinceStartup-began>45f){Debug.LogError("GROUPPAIR TIMEOUT");Application.Quit(2);}}
}
